CREATE TABLE jawf_term_source_private.completion_before (kind text NOT NULL,id uuid NOT NULL,original jsonb NOT NULL,PRIMARY KEY(kind,id));
ALTER TABLE jawf_term_source_private.completion_before ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON jawf_term_source_private.completion_before FROM PUBLIC,anon,authenticated;

CREATE FUNCTION jawf_term_source_private.apply_completion()
RETURNS integer LANGUAGE plpgsql SET search_path='pg_catalog','public','jawf_term_source_private' AS $$
DECLARE p jsonb; n jsonb; src public.existing_schedule_source_rows%ROWTYPE; g public.delivery_groups%ROWTYPE;
 old_s public.schedule_sessions%ROWTYPE; j jsonb; sid uuid; oid uuid; taid uuid; cnt integer:=0;
 v constant uuid:='286e37d4-d45c-5942-b8e0-facdfed3081f'; c constant uuid:='0d0e89c6-d041-43de-a448-249070ef6c81';
BEGIN
 IF session_user NOT IN ('postgres','supabase_admin') THEN RAISE EXCEPTION 'JAWF_OPERATOR_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(9282026,1);
 IF (SELECT count(*) FROM schedule_versions WHERE id IN (v,'9ef411ff-0e91-e754-2985-44799be1255e') AND status='draft' AND college_id=c)<>2
 OR (SELECT count(*) FROM existing_schedule_source_rows WHERE schedule_version_id IN (v,'9ef411ff-0e91-e754-2985-44799be1255e'))<>67
 OR (SELECT count(*) FROM schedule_sessions WHERE schedule_version_id IN (v,'9ef411ff-0e91-e754-2985-44799be1255e'))<>7
 THEN RAISE EXCEPTION 'JAWF_COMPLETION_BASELINE_DRIFT'; END IF;
 INSERT INTO jawf_term_source_private.completion_before SELECT 'source',id,to_jsonb(r) FROM existing_schedule_source_rows r WHERE schedule_version_id IN (v,'9ef411ff-0e91-e754-2985-44799be1255e');
 INSERT INTO jawf_term_source_private.completion_before SELECT 'session',id,to_jsonb(s) FROM schedule_sessions s WHERE schedule_version_id=v;
 INSERT INTO jawf_term_source_private.completion_before SELECT 'version',id,to_jsonb(s) FROM schedule_versions s WHERE id IN (v,'9ef411ff-0e91-e754-2985-44799be1255e');
 INSERT INTO jawf_term_source_private.completion_before SELECT 'assignment',id,to_jsonb(t) FROM teaching_assignments t WHERE id='1781ca5a-14d7-443f-9f94-aa570074b223';
 FOR n IN SELECT value FROM jawf_term_source_private.completion_plan, jsonb_array_elements(plan->'provisional') LOOP
  INSERT INTO instructors(id,college_id,department_id,full_name,employment_type,max_weekly_hours,external_source,notes)
  SELECT (n->>'id')::uuid,c,ap.department_id,'[اسم من جدول هذا الفصل] '||(n->>'raw_name'),'unknown',NULL,
    'JWF26F-NAME:'||(n->>'key'),'اسم المصدر لهذا الترم فقط؛ هوية غير موثقة، دون إسناد مالي. لا يثبت الربط بأي موظف مشابه الاسم.'
  FROM existing_schedule_source_rows r JOIN academic_cohorts ac ON ac.id=r.cohort_id JOIN academic_programs ap ON ap.id=ac.program_id
  WHERE r.schedule_version_id=v AND r.raw_teacher=n->>'raw_name' LIMIT 1;
 END LOOP;
 -- One college-wide version includes both independent programs and all expected groups.
 UPDATE existing_schedule_source_rows SET schedule_version_id=v WHERE schedule_version_id='9ef411ff-0e91-e754-2985-44799be1255e';
 FOR p IN SELECT value FROM jawf_term_source_private.completion_plan,jsonb_array_elements(plan->'placements') LOOP
  SELECT * INTO STRICT src FROM existing_schedule_source_rows WHERE id=(p->>'source_row_id')::uuid AND source_id=p->>'source_id' AND schedule_version_id=v FOR UPDATE;
  SELECT * INTO STRICT g FROM delivery_groups WHERE id=src.delivery_group_id AND active AND NOT is_obsolete;
  SELECT id INTO STRICT oid FROM course_offerings WHERE college_id=c AND term_id=src.term_id AND plan_course_id=src.plan_course_id AND is_active;
  sid:=coalesce(src.schedule_session_id,gen_random_uuid()); taid:=src.teaching_assignment_id;
  IF src.source_id='JWF-SCI-2026-S1-L3-R26' THEN taid:=NULL; END IF;
  SELECT * INTO old_s FROM schedule_sessions WHERE id=sid;
  UPDATE existing_schedule_source_rows SET instructor_ids=ARRAY[(p->>'instructor_id')::uuid],teaching_assignment_id=taid,
   day_of_week=(p->>'day_of_week')::smallint,start_time=(p->>'start_time')::time,end_time=(p->>'end_time')::time,room_id=(p->>'room_id')::uuid,
   notes=concat_ws(E'\n',notes,'إنجاز هذا الترم بتفويض المستخدم: موعد تشغيلي معالج من التعارضات؛ الموعد الأصلي محفوظ في raw_time/raw_day ونسخة المصدر. الأعداد تقديرية. استثناء الحضور لهذا الترم عند الحاجة؛ لا تعديل للتوفر الدائم.')
   WHERE id=src.id;
  j:=coalesce(to_jsonb(old_s), '{}'::jsonb)||jsonb_build_object('id',sid,'schedule_version_id',v,'college_id',c,'course_offering_id',oid,
    'teaching_assignment_id',taid,'instructor_id',(p->>'instructor_id')::uuid,'cohort_id',src.cohort_id,'delivery_group_id',src.delivery_group_id,
    'plan_course_component_id',src.component_id,'room_id',(p->>'room_id')::uuid,'day_of_week',(p->>'day_of_week')::smallint,
    'start_time',p->>'start_time','end_time',p->>'end_time','session_type',CASE WHEN (SELECT component_type FROM plan_course_components WHERE id=src.component_id)='practical' THEN 'lab' ELSE 'lecture' END,
    'study_system','regular','source_type','manual','expected_students',g.expected_students,'is_locked',false,'replaced_by_split',false,'created_at',coalesce(old_s.created_at,now()),'updated_at',now());
  j:=to_jsonb(jsonb_populate_record(NULL::schedule_sessions,j));
  INSERT INTO jawf_term_source_private.sessions(session_id,source_row_id,version_id,expected,source_original) VALUES(sid,src.id,v,j,to_jsonb(src))
   ON CONFLICT(session_id) DO UPDATE SET expected=EXCLUDED.expected;
  IF old_s.id IS NULL THEN INSERT INTO schedule_sessions SELECT (jsonb_populate_record(NULL::schedule_sessions,j)).*;
  ELSE UPDATE schedule_sessions SET instructor_id=(p->>'instructor_id')::uuid,teaching_assignment_id=taid,room_id=(p->>'room_id')::uuid,
   day_of_week=(p->>'day_of_week')::smallint,start_time=(p->>'start_time')::time,end_time=(p->>'end_time')::time WHERE id=sid; END IF;
  UPDATE existing_schedule_source_rows SET schedule_session_id=sid,status='imported',pending_reasons=ARRAY[]::text[] WHERE id=src.id;
  cnt:=cnt+1;
 END LOOP;
 UPDATE teaching_assignments SET is_active=false WHERE id='1781ca5a-14d7-443f-9f94-aa570074b223';
 UPDATE existing_schedule_source_rows SET pending_reasons=ARRAY[]::text[],notes=concat_ws(E'\n',notes,'بحث التخرج ساعتان خارج الجدول الأسبوعي والنصاب؛ مستثنى صراحة من التسكين.') WHERE schedule_version_id=v AND source_id='JWF-PA-2026-S1-R11';
 UPDATE schedule_versions SET name='الجوف — معلم مجال العلوم والإدارة العامة — الفصل الأول 2026–2027',notes='جدول موحد لبرنامجي الجوف بمجموعات طلاب مستقلة. 66 محاضرة و153 ساعة أسبوعية. استضافة في قاعات التربية والعلوم الإدارية. الأسماء غير الموثقة للعرض والحجز فقط دون إسناد مالي. استثناء هذا الترم بتفويض المستخدم؛ المواعيد الأصلية محفوظة، والجدول التشغيلي أعيد تسكينه لمنع التداخل. بحث التخرج خارج الجدول الأسبوعي والنصاب.' WHERE id=v;
 UPDATE schedule_versions SET name='مرجع نقل الإدارة العامة — مضمن في جدول الجوف الموحد',notes='جميع صفوف المصدر مضمنة في النسخة 286e37d4-d45c-5942-b8e0-facdfed3081f؛ لا توجد محاضرات في هذا المرجع.' WHERE id='9ef411ff-0e91-e754-2985-44799be1255e';
 INSERT INTO audit_logs(actor_id,action,entity,entity_id,college_id,details) VALUES(NULL,'jawf.term_completion','schedule_versions',v,c,jsonb_build_object('sessions',cnt,'source_rows',67,'authority','User explicitly authorized all term exceptions, solving and publication','source_backup','jawf_term_source_private.completion_before','source_only_names',10));
 RETURN cnt;
END; $$;
REVOKE ALL ON FUNCTION jawf_term_source_private.apply_completion() FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.jawf_term_provisional_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='pg_catalog','public' AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM instructors WHERE id=NEW.instructor_id AND external_source LIKE 'JWF26F-NAME:%') THEN
  IF TG_TABLE_NAME='teaching_assignments' THEN RAISE EXCEPTION 'JAWF_SOURCE_NAME_NOT_HR_ASSIGNMENT'; END IF;
  IF NEW.teaching_assignment_id IS NOT NULL OR NOT public.jawf_term_source_session_allowed(NEW) THEN RAISE EXCEPTION 'JAWF_SOURCE_NAME_OUTSIDE_APPROVED_TERM'; END IF;
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER jawf_provisional_assignment BEFORE INSERT OR UPDATE OF instructor_id ON teaching_assignments FOR EACH ROW EXECUTE FUNCTION jawf_term_provisional_guard();
CREATE TRIGGER jawf_provisional_session BEFORE INSERT OR UPDATE ON schedule_sessions FOR EACH ROW EXECUTE FUNCTION jawf_term_provisional_guard();

CREATE FUNCTION public.jawf_term_completion_verified(p_version uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='pg_catalog','public','jawf_term_source_private' AS $$
 SELECT p_version='286e37d4-d45c-5942-b8e0-facdfed3081f'::uuid
 AND (SELECT count(*) FROM schedule_sessions WHERE schedule_version_id=p_version)=66
 AND (SELECT count(*) FROM existing_schedule_source_rows WHERE schedule_version_id=p_version AND schedule_session_id IS NOT NULL AND status='imported')=66
 AND NOT EXISTS(SELECT 1 FROM schedule_sessions s WHERE s.schedule_version_id=p_version AND NOT public.jawf_term_source_session_allowed(s))
 AND NOT EXISTS(SELECT 1 FROM schedule_sessions s JOIN rooms r ON r.id=s.room_id WHERE s.schedule_version_id=p_version AND (s.expected_students>r.capacity OR s.start_time<'08:00' OR s.end_time>'14:00'))
 AND NOT EXISTS(SELECT 1 FROM schedule_sessions s JOIN schedule_sessions other ON other.id<>s.id AND other.day_of_week=s.day_of_week AND other.start_time<s.end_time AND other.end_time>s.start_time
 JOIN schedule_versions ov ON ov.id=other.schedule_version_id JOIN academic_terms ot ON ot.id=ov.academic_term_id
 WHERE s.schedule_version_id=p_version AND (ov.status='published' OR ov.id=p_version) AND ot.start_date<='2026-12-26' AND ot.end_date>='2026-09-06'
 AND (s.room_id=other.room_id OR s.instructor_id=other.instructor_id OR EXISTS(SELECT 1 FROM faculty_identity_links a JOIN faculty_identity_links b ON a.identity_id=b.identity_id WHERE a.instructor_id=s.instructor_id AND b.instructor_id=other.instructor_id)))
 AND NOT EXISTS(SELECT 1 FROM schedule_sessions s JOIN schedule_sessions o ON o.schedule_version_id=s.schedule_version_id AND o.id>s.id AND o.cohort_id=s.cohort_id AND o.day_of_week=s.day_of_week AND o.start_time<s.end_time AND o.end_time>s.start_time JOIN delivery_groups a ON a.id=s.delivery_group_id JOIN delivery_groups b ON b.id=o.delivery_group_id WHERE s.schedule_version_id=p_version AND a.group_number=b.group_number);
$$;
REVOKE ALL ON FUNCTION public.jawf_term_completion_verified(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.jawf_term_completion_verified(uuid) TO authenticated;

CREATE FUNCTION public.jawf_term_completion_coverage(p_version uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='pg_catalog','public' AS $$
 WITH expected AS (SELECT g.id,p.weekly_contact_hours::numeric hours FROM delivery_groups g JOIN academic_cohorts c ON c.id=g.cohort_id JOIN plan_course_components p ON p.id=g.component_id WHERE c.college_id='0d0e89c6-d041-43de-a448-249070ef6c81' AND c.term_id='a0963d5e-b042-4174-a325-a68599eae8ff' AND c.active AND g.active AND NOT g.is_obsolete AND coalesce(p.is_timetabled,true)),
 actual AS(SELECT delivery_group_id,sum(extract(epoch FROM(end_time-start_time))/3600) hours,count(*) n FROM schedule_sessions WHERE schedule_version_id=p_version AND NOT replaced_by_split GROUP BY delivery_group_id),
 assignments AS(SELECT delivery_group_id,count(*) n FROM teaching_assignments WHERE college_id='0d0e89c6-d041-43de-a448-249070ef6c81' AND is_active GROUP BY delivery_group_id),
 a AS(SELECT e.*,coalesce(s.hours,0) scheduled,coalesce(s.n,0) sessions,coalesce(t.n,0) assignments FROM expected e LEFT JOIN actual s ON s.delivery_group_id=e.id LEFT JOIN assignments t ON t.delivery_group_id=e.id)
 SELECT jsonb_build_object('total_groups',count(*),'assigned_exactly_once',count(*) FILTER(WHERE assignments=1),'unassigned_groups',count(*) FILTER(WHERE assignments=0),'multi_assigned_groups',count(*) FILTER(WHERE assignments>1),
 'provisional_source_groups',count(*) FILTER(WHERE assignments=0 AND sessions=1),'temporary_assignment_exception',public.jawf_term_completion_verified(p_version),
 'groups_with_sessions',count(*) FILTER(WHERE sessions>0),'groups_without_sessions',count(*) FILTER(WHERE sessions=0),'exact_hours_groups',count(*) FILTER(WHERE hours=scheduled),'short_hours_groups',count(*) FILTER(WHERE scheduled<hours),'over_hours_groups',count(*) FILTER(WHERE scheduled>hours),
 'required_hours',sum(hours),'scheduled_hours',sum(scheduled),'missing_hours',sum(greatest(hours-scheduled,0)),'extra_hours',sum(greatest(scheduled-hours,0)),
 'complete',count(*)=66 AND sum(hours)=153 AND sum(scheduled)=153 AND bool_and(hours=scheduled AND sessions=1 AND assignments<=1) AND public.jawf_term_completion_verified(p_version)) FROM a;
$$;
REVOKE ALL ON FUNCTION public.jawf_term_completion_coverage(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.jawf_term_completion_coverage(uuid) TO authenticated;
DO $$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.schedule_version_delivery_coverage(uuid,uuid)'::regprocedure);
 IF position('  WITH cohort_batches AS (' IN d)=0 THEN RAISE EXCEPTION 'JAWF_COVERAGE_DEFINITION_DRIFT'; END IF;
 d:=replace(d,'  WITH cohort_batches AS (',E'  IF p_college_id=''0d0e89c6-d041-43de-a448-249070ef6c81''::uuid AND p_schedule_version_id=''286e37d4-d45c-5942-b8e0-facdfed3081f''::uuid THEN RETURN public.jawf_term_completion_coverage(p_schedule_version_id); END IF;\n  WITH cohort_batches AS (');
 EXECUTE d;
END; $$;
SELECT jawf_term_source_private.apply_completion();
DO $$ BEGIN IF NOT public.jawf_term_completion_verified('286e37d4-d45c-5942-b8e0-facdfed3081f') OR NOT (public.jawf_term_completion_coverage('286e37d4-d45c-5942-b8e0-facdfed3081f')->>'complete')::boolean THEN RAISE EXCEPTION 'JAWF_COMPLETION_VERIFICATION_FAILED'; END IF; END; $$;
SET CONSTRAINTS ALL IMMEDIATE;
COMMIT;
